Give the code of Kruskal algo
In competitive programming, Kruskal’s Algorithm is the go-to for finding the Minimum
Spanning Tree (MST) because it is easy to implement using Disjoint Set Union (DSU).
The algorithm follows a greedy approach:
1. Sort all edges in non-decreasing order of their weights.
2. Pick the smallest edge. Check if it forms a cycle with the spanning tree formed so far
using DSU.
3. If it doesn't form a cycle, include this edge. Else, discard it.
4. Repeat until there are (V−1) edges in the MST.
C++ Implementation (using DSU)
C++
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
// DSU Class to handle cycle detection and union
class DSU {
    vector<int> parent, rank;
public:
    DSU(int n) {
        parent.resize(n);
        rank.resize(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;
    }

// Find with Path Compression
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    // Union by Rank
    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            if (rank[root_i] < rank[root_j]) parent[root_i] = root_j;
            else if (rank[root_i] > rank[root_j]) parent[root_j] = root_i;
            else {
                parent[root_i] = root_j;
                rank[root_j]++;
            }
        }
    }
};
struct Edge {
    int u, v, weight;
    bool operator<(Edge const& other) {
        return weight < other.weight;
    }
};
int kruskal(int V, vector<Edge>& edges) {
    sort(edges.begin(), edges.end()); // Step 1: Sort edges

    DSU dsu(V);
    int mst_weight = 0;
    int edges_count = 0;
    for (Edge e : edges) {
        // Step 2: Check if u and v are in different components
        if (dsu.find(e.u) != dsu.find(e.v)) {

dsu.unite(e.u, e.v);
            mst_weight += e.weight;
            edges_count++;
            cout << "Edge: " << e.u << " - " << e.v << " | Weight: " << e.we
        }
    }
    return mst_weight;
}
int main() {
    int V = 4; // Number of vertices
    vector<Edge> edges = {
        {0, 1, 10}, {0, 2, 6}, {0, 3, 5}, {1, 3, 15}, {2, 3, 4}
    };
    int total_weight = kruskal(V, edges);
    cout << "Total weight of MST: " << total_weight << endl;
    return 0;
}
Complexity Analysis
Time Complexity: O(ElogE) or O(ElogV). Sorting the edges takes O(ElogE). The DSU
operations (Find and Union) are nearly O(1) on average due to path compression and
union by rank.
Space Complexity: O(V+E) to store the graph and the DSU structures.
Interviewer Checkpoint (Visa Style)
Question: "Why do we use DSU in Kruskal’s instead of a simple BFS/DFS for cycle
detection?"
Answer: "Using BFS/DFS to check for a cycle every time we add an edge would take
O(V), making the total complexity O(E⋅V). DSU with path compression and union by
rank allows us to do this check in nearly constant time, O(α(V)), making the algorithm
much faster for large graphs."

typedef pair<int, int> pii; // {weight, node}
int primMST(int V, vector<vector<pii>>& adj) {
    // Min-priority queue to pick the smallest weight edge
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    vector<int> key(V, 1e9);      // Minimum weight to connect node to MST
    vector<bool> inMST(V, false); // Tracks if node is already in MST
    int mst_weight = 0;
    // Start from node 0
    pq.push({0, 0});
    key[0] = 0;
    while (!pq.empty()) {
        int u = pq.top().second;
        int w = pq.top().first;
        pq.pop();
        // If node is already in MST, skip it
        if (inMST[u]) continue;
        // Add weight to total and mark node as included
        inMST[u] = true;
        mst_weight += w;
        // Explore neighbors
        for (auto& neighbor : adj[u]) {
            int v = neighbor.first;
            int weight = neighbor.second;
            // If v is not in MST and weight is smaller than current key
            if (!inMST[v] && weight < key[v]) {
                key[v] = weight;
                pq.push({key[v], v});
            }
        }

}
    return mst_weight;
}
